
% X is generated by CreateRandomSolution function which has 1 row and i+j
% columns. the first i elemnts of X belong to the suppliers and the i+1 to
% i+j blong to the customers.
model=Model();
X=CreateRandomSolution(model);

%% recalling number of suppliers (i) and customers (j)
i=model.i;
j=model.j;
 
%% seprate to the supply (yy1) and demand (yy2) section of chromosome

yy1=X(1:i);       %supply section
yy2=X(i+1:i+j);   %demand section

[sortedx1, y1]= sort(yy1) %sort the supply section
[sortedx2, y2]= sort(yy2) %sort the demand section

% define a zero i*j matix as transportation matrix (supply-demand matrix)
yaloc=zeros(model.i,model.j); 

% check if the demands are not satisfied yet
while sum(model.b)>0
 
% check the minimum between the most left element of a and b and allocate
% it to the elment (y1(1),y2(1)) of matrix yalco

    yaloc(y1(1),y2(1))=min(model.a(y1(1)),model.b(y2(1)));

% subtract the allocated value from the most left element of a and b.
    model.a(y1(1))=model.a(y1(1))-yaloc(y1(1),y2(1));
    model.b(y2(1))=model.b(y2(1))-yaloc(y1(1),y2(1));
    
% check if either supply or demands is fulfilled, and the zero element is
% extarcted from the chromosome.

    if model.a(y1(1))==0
       y1(1)=[];
    end
    if model.b(y2(1))==0
       y2(1)=[];
    end
end

% check which elements in yaloc positive. Those elements have distribution
% between the nodes, so it calculates the fixed cost for that
% node
ff=zeros(model.i,1);

for ii=1:model.i
    if sum(yaloc')'(ii)>0
        ff(ii)=1;
    end
end
cc=sum(sum(ff.*model.f));

%calcualte the transportation cost. 
bb=sum(sum(yaloc.*model.cij));

%calculate total cost
yaloc
TotalCost=bb+cc
